import unittest
from candidate import intersperse


class TestIntersperse(unittest.TestCase):
    def test_empty_list_returns_empty_list(self):
        self.assertEqual(intersperse([], 4), [])

    def test_single_element_no_delimiter_inserted(self):
        self.assertEqual(intersperse([1], 4), [1])

    def test_two_elements_delimiter_between(self):
        self.assertEqual(intersperse([1, 2], 4), [1, 4, 2])

    def test_three_elements_two_delimiters(self):
        self.assertEqual(intersperse([1, 2, 3], 4), [1, 4, 2, 4, 3])

    def test_four_elements_three_delimiters(self):
        self.assertEqual(intersperse([1, 2, 3, 4], 0), [1, 0, 2, 0, 3, 0, 4])

    def test_negative_numbers_as_elements(self):
        self.assertEqual(intersperse([-1, -2, -3], 5), [-1, 5, -2, 5, -3])

    def test_negative_delimiter(self):
        self.assertEqual(intersperse([1, 2, 3], -1), [1, -1, 2, -1, 3])

    def test_zero_as_delimiter(self):
        self.assertEqual(intersperse([1, 2, 3], 0), [1, 0, 2, 0, 3])

    def test_zero_as_element(self):
        self.assertEqual(intersperse([0, 0, 0], 1), [0, 1, 0, 1, 0])

    def test_delimiter_same_as_elements(self):
        self.assertEqual(intersperse([4, 4, 4], 4), [4, 4, 4, 4, 4])

    def test_large_list(self):
        numbers = list(range(1, 11))
        result = intersperse(numbers, 99)
        expected = []
        for i, n in enumerate(numbers):
            expected.append(n)
            if i < len(numbers) - 1:
                expected.append(99)
        self.assertEqual(result, expected)

    def test_two_elements_different_values(self):
        self.assertEqual(intersperse([10, 20], 5), [10, 5, 20])

    def test_mixed_positive_negative_elements(self):
        self.assertEqual(intersperse([1, -1, 2, -2], 0), [1, 0, -1, 0, 2, 0, -2])

    def test_result_length_empty_list(self):
        self.assertEqual(len(intersperse([], 4)), 0)

    def test_result_length_single_element(self):
        self.assertEqual(len(intersperse([5], 3)), 1)

    def test_result_length_n_elements(self):
        self.assertEqual(len(intersperse([1, 2, 3, 4, 5], 0)), 9)

    def test_none_as_numbers_raises_type_error(self):
        with self.assertRaises(TypeError):
            intersperse(None, 4)

    def test_string_as_numbers_raises_type_error(self):
        with self.assertRaises(TypeError):
            intersperse("abc", 4)

    def test_integer_as_numbers_raises_type_error(self):
        with self.assertRaises(TypeError):
            intersperse(123, 4)

    def test_none_as_delimiter(self):
        with self.assertRaises(TypeError):
            intersperse([1, 2, 3], None)

    def test_float_as_delimiter(self):
        self.assertEqual(intersperse([1, 2, 3], 0.5), [1, 0.5, 2, 0.5, 3])

    def test_does_not_modify_original_list(self):
        original = [1, 2, 3]
        original_copy = original[:]
        intersperse(original, 4)
        self.assertEqual(original, original_copy)

    def test_returns_new_list_not_same_object(self):
        numbers = [1, 2, 3]
        result = intersperse(numbers, 4)
        self.assertIsNot(result, numbers)

    def test_single_element_zero(self):
        self.assertEqual(intersperse([0], 5), [0])

    def test_single_element_negative(self):
        self.assertEqual(intersperse([-5], 3), [-5])


if __name__ == '__main__':
    unittest.main()
